<template>
  <v-dialog
    :model-value="show"
    @update:model-value="updateShow"
    max-width="500px"
  >
    <v-card>
      <v-card-title class="text-h5">
        <span>{{
          item?.isNew ? "Add New User" : `${item?.user} Details`
        }}</span>
      </v-card-title>

      <v-card-text>
        <v-container>
          <v-row justify="center">
            <v-col cols="12">
              <v-text-field
                v-if="item"
                v-model="localUsername"
                label="Username"
                variant="outlined"
                class="mb-3"
              ></v-text-field>
              <v-text-field
                v-if="item"
                v-model="localGuild"
                label="Guild"
                variant="outlined"
                class="mb-3"
              ></v-text-field>
              <v-text-field
                v-if="item"
                v-model.number="localDkp"
                label="DKP"
                type="number"
                variant="outlined"
                class="mb-3"
              ></v-text-field>
              <v-text-field
                v-if="item"
                v-model="localClass"
                label="Class"
                variant="outlined"
                class="mb-3"
              ></v-text-field>
              <v-text-field
                v-if="item"
                v-model="localLevel"
                label="Level"
                variant="outlined"
                class="mb-3"
              ></v-text-field>
              <v-text-field
                v-if="item"
                v-model="localDetails"
                label="Details"
                variant="outlined"
                class="mb-3"
                maxlength="10"
                counter="10"
              ></v-text-field>
              <v-text-field
                v-if="item"
                v-model="localConstantParty"
                label="Constant Party"
                variant="outlined"
                class="mb-3"
              ></v-text-field>
              <div class="text-subtitle-2 mb-2">
                Total Event Attendance: {{ attendanceCount }}
              </div>
            </v-col>
            <v-col cols="12" class="attendance-section pa-4">
              <v-list-subheader>Attendance by Event Type:</v-list-subheader>
              <v-table dense>
                <template #header>
                  <tr>
                    <th>Event Type</th>
                    <th>Attendance Count</th>
                  </tr>
                </template>
                <template #default>
                  <tr>
                    <td>Field Raids</td>
                    <td>
                      <v-text-field
                        v-model.number="localFieldRaids"
                        type="number"
                        variant="outlined"
                        min="0"
                        density="compact"
                        hide-details
                        style="max-width: 100px"
                      ></v-text-field>
                    </td>
                  </tr>
                  <tr>
                    <td>Call To Arms</td>
                    <td>
                      <v-text-field
                        v-model.number="localCallToArms"
                        type="number"
                        variant="outlined"
                        min="0"
                        density="compact"
                        hide-details
                        style="max-width: 100px"
                      ></v-text-field>
                    </td>
                  </tr>
                  <tr>
                    <td>Epics</td>
                    <td>
                      <v-text-field
                        v-model.number="localEpics"
                        type="number"
                        variant="outlined"
                        min="0"
                        density="compact"
                        hide-details
                        style="max-width: 100px"
                      ></v-text-field>
                    </td>
                  </tr>
                  <tr>
                    <td>Clan Hall/Fort</td>
                    <td>
                      <v-text-field
                        v-model.number="localClanFort"
                        type="number"
                        variant="outlined"
                        min="0"
                        density="compact"
                        hide-details
                        style="max-width: 100px"
                      ></v-text-field>
                    </td>
                  </tr>
                  <tr>
                    <td>Siege</td>
                    <td>
                      <v-text-field
                        v-model.number="localSiege"
                        type="number"
                        variant="outlined"
                        min="0"
                        density="compact"
                        hide-details
                        style="max-width: 100px"
                      ></v-text-field>
                    </td>
                  </tr>
                  <tr>
                    <td>Camera Watcher</td>
                    <td>
                      <v-text-field
                        v-model.number="localCameraWatcher"
                        type="number"
                        variant="outlined"
                        min="0"
                        density="compact"
                        hide-details
                        style="max-width: 100px"
                      ></v-text-field>
                    </td>
                  </tr>
                </template>
              </v-table>
            </v-col>
          </v-row>
        </v-container>
      </v-card-text>

      <v-card-actions>
        <v-btn
          v-if="!item?.isNew"
          color="error"
          variant="text"
          @click="deleteUser"
          prepend-icon="mdi-delete"
        >
          Delete User
        </v-btn>
        <v-spacer></v-spacer>
        <v-btn color="primary" variant="text" @click="updateShow(false)">
          Cancel
        </v-btn>
        <v-btn color="primary" variant="text" @click="saveChanges">
          Save
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script setup>
import { ref, watch, computed, defineProps, defineEmits } from "vue";
import { ref as dbRef, set } from "firebase/database";
import { inject } from "vue";
import { useAuth } from "@/composables/useAuth";

const props = defineProps({
  modelValue: {
    type: Boolean,
    required: true,
  },
  item: {
    type: Object,
    default: null,
  },
});

const emit = defineEmits(["update:modelValue", "saved"]);

// Computed property for v-model handling
const show = computed({
  get: () => props.modelValue,
  set: (value) => emit("update:modelValue", value),
});

const updateShow = (value) => {
  emit("update:modelValue", value);
};

// Get database instance and auth at setup time
const db = inject("db");
const { currentUser } = useAuth();
const localDkp = ref(0);
const localUsername = ref("");
const localGuild = ref("");
const localClass = ref("");
const localLevel = ref("");
const localDetails = ref("");
const localConstantParty = ref("");
const attendanceCount = ref(0);
const attendanceByType = ref({});

// Local refs for editable attendance counts
const localFieldRaids = ref(0);
const localCallToArms = ref(0);
const localEpics = ref(0);
const localClanFort = ref(0);
const localSiege = ref(0);
const localCameraWatcher = ref(0);

const loadAttendanceFromUser = () => {
  if (!props.item) return;

  // Read eventsAttended from user object or initialize with zeros
  const eventsAttended = props.item.eventsAttended || {};

  localFieldRaids.value = eventsAttended.fieldRaids || 0;
  localCallToArms.value = eventsAttended.callToArms || 0;
  localEpics.value = eventsAttended.epics || 0;
  localClanFort.value = eventsAttended.clanFort || 0;
  localSiege.value = eventsAttended.siege || 0;
  localCameraWatcher.value = eventsAttended.cameraWatcher || 0;

  // Update display objects
  attendanceByType.value = {
    "Field Raids": localFieldRaids.value,
    "Call To Arms": localCallToArms.value,
    Epics: localEpics.value,
    "Clan Hall/Fort": localClanFort.value,
    Siege: localSiege.value,
    "Camera Watcher": localCameraWatcher.value,
  };

  attendanceCount.value =
    localFieldRaids.value +
    localCallToArms.value +
    localEpics.value +
    localClanFort.value +
    localSiege.value;
  localCameraWatcher.value;
};

// Watch for item changes to update local values
watch(
  () => props.item,
  (newItem) => {
    if (newItem) {
      localDkp.value = newItem.dkp || 0;
      localUsername.value = newItem.user || "";
      localGuild.value = newItem.guild || "";
      localClass.value = newItem.class || "";
      localLevel.value = newItem.level || "";
      localDetails.value = newItem.details || "";
      localConstantParty.value = newItem.constantParty || "";
      loadAttendanceFromUser();
    }
  },
  { immediate: true }
);

// Function to log DKP changes to audit log
const logDkpChange = async (
  userId,
  username,
  oldDkp,
  newDkp,
  changeType = "manual_edit"
) => {
  if (!db || oldDkp === newDkp) return;

  try {
    const timestamp = new Date().toISOString();
    const auditLogRef = dbRef(db, `audit_logs/${Date.now()}_${userId}`);

    // Get current user information for audit trail
    const changedByUser = currentUser.value;
    const changedByInfo = changedByUser
      ? {
          email: changedByUser.email,
          uid: changedByUser.uid,
          displayName: changedByUser.displayName || changedByUser.email,
        }
      : {
          email: "unknown",
          uid: "unknown",
          displayName: "Unknown User",
        };

    const logEntry = {
      userId: userId,
      username: username,
      changeType: changeType, // 'manual_edit', 'event_award', etc.
      oldValue: Number(oldDkp),
      newValue: Number(newDkp),
      timestamp: timestamp,
      changedBy: changedByInfo.displayName,
      changedByEmail: changedByInfo.email,
      changedByUid: changedByInfo.uid,
    };

    await set(auditLogRef, logEntry);
    console.log("DKP change logged:", logEntry);
  } catch (error) {
    console.error("Error logging DKP change:", error);
  }
};

const saveChanges = async () => {
  if (!props.item || !db || !localUsername.value) return;

  try {
    // For new users, use the username as the ID; for existing users, use the existing ID
    const userId = props.item.isNew ? localUsername.value : props.item.id;
    const userRef = dbRef(db, `dkp/${userId}`);

    // Get the old DKP value for audit logging
    const oldDkp = props.item.dkp || 0;
    const newDkp = Number(localDkp.value);

    // Log the DKP change if it's not a new user and DKP has changed
    if (!props.item.isNew && oldDkp !== newDkp) {
      await logDkpChange(
        userId,
        localUsername.value,
        oldDkp,
        newDkp,
        "manual_edit"
      );
    }

    // Prepare the user data object
    const userData = {
      user: localUsername.value,
      guild: localGuild.value || "",
      dkp: newDkp,
      class: localClass.value || "",
      level: localLevel.value || "",
      details: localDetails.value || "",
      constantParty: localConstantParty.value || 0,
      eventsAttended: {
        fieldRaids: Number(localFieldRaids.value) || 0,
        callToArms: Number(localCallToArms.value) || 0,
        epics: Number(localEpics.value) || 0,
        clanFort: Number(localClanFort.value) || 0,
        siege: Number(localSiege.value) || 0,
        cameraWatcher: Number(localCameraWatcher.value) || 0,
      },
    };

    // Preserve existing date fields if they exist (for existing users)
    if (!props.item.isNew) {
      if (props.item.createdDate) {
        userData.createdDate = props.item.createdDate;
      }

      if (props.item.latestEventAttended) {
        userData.latestEventAttended = props.item.latestEventAttended;
      }
    } else {
      // For new users, set createdDate to current timestamp
      userData.createdDate = new Date().toISOString();
    }

    await set(userRef, userData);

    emit("update:modelValue", false);
    emit("saved");
  } catch (error) {
    console.error("Error saving user:", error);
  }
};

const deleteUser = async () => {
  if (!props.item || !db || props.item.isNew) return;

  // Show confirmation dialog
  const confirmed = confirm(
    `Are you sure you want to delete user "${props.item.user}"?\n\nThis will mark them as deleted but preserve their data for record keeping.`
  );

  if (!confirmed) return;

  try {
    const userId = props.item.id;
    const userRef = dbRef(db, `dkp/${userId}`);

    // Get current user data and add deleted flag
    const updatedUserData = {
      user: props.item.user,
      guild: props.item.guild || "",
      dkp: props.item.dkp || 0,
      class: props.item.class || "",
      level: props.item.level || "",
      details: props.item.details || "",
      constantParty: props.item.constantParty || "",
      eventsAttended: props.item.eventsAttended || {
        fieldRaids: 0,
        callToArms: 0,
        epics: 0,
        clanFort: 0,
        siege: 0,
        cameraWatcher: 0,
      },
      deleted: true,
      deletedAt: new Date().toISOString(),
      deletedBy: currentUser.value?.email || "unknown",
    };

    await set(userRef, updatedUserData);

    // Log the deletion to audit log
    await logDkpChange(
      userId,
      props.item.user,
      props.item.dkp || 0,
      props.item.dkp || 0,
      "user_deleted"
    );

    emit("update:modelValue", false);
    emit("saved");
  } catch (error) {
    console.error("Error deleting user:", error);
    alert("Error deleting user. Please try again.");
  }
};
</script>

<style scoped>
.v-card {
  background-color: #0a1025 !important;
  border: #1f9ee5 2px ridge;
  box-shadow: #1f9ee5 0px 0px 30px 2px;
  color: #eaf1ff;
}

.v-card-title {
  color: #eaf1ff !important;
  border-bottom: 1px solid #1f9ee5;
}

.attendance-section {
  border-radius: 4px;
  background-color: rgba(31, 158, 229, 0.05);
  border: #1f9ee5 1px solid;
  max-height: 250px;
  overflow-y: auto;
}

.v-text-field {
  color: #eaf1ff !important;
}

.v-text-field:deep(input) {
  color: #eaf1ff !important;
}

.v-text-field:deep(label) {
  color: #1f9ee5 !important;
}

.v-text-field:deep(.v-field__outline) {
  color: #1f9ee5 !important;
}

.v-table {
  background-color: transparent !important;
  color: #eaf1ff !important;
}

.v-table:deep(th) {
  background-color: rgba(31, 158, 229, 0.1) !important;
  color: #eaf1ff !important;
  border-bottom: 1px solid #1f9ee5 !important;
}

.v-table:deep(td) {
  color: #eaf1ff !important;
  border-bottom: 1px solid rgba(31, 158, 229, 0.3) !important;
}

.v-btn {
  color: #1f9ee5 !important;
}

.v-list-subheader {
  color: #1f9ee5 !important;
  font-weight: bold;
}

.text-subtitle-2 {
  color: #eaf1ff !important;
}
</style>
